// ---------------------------------------------------------------------------------------------
// S1: the usermod must see its own topics after WLED strips the device prefix.
// ---------------------------------------------------------------------------------------------
static void testClassifyTopic() {
  using pixc::Topic;
  const char* base = "epixc/v1/d/aabbccddeeff";

  // What WLED actually delivers (mqtt.cpp strips mqttDeviceTopic). This is the case that was dead.
  CHECK(pixc::classifyTopic("/cfg", base) == Topic::Cfg);
  CHECK(pixc::classifyTopic("/reset", base) == Topic::Reset);
  CHECK(pixc::classifyTopic("/ota", base) == Topic::Ota);

  // The unstripped form, for a delivery path that does not strip.
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/cfg", base) == Topic::Cfg);
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/ota", base) == Topic::Ota);

  // Exact match only: our own publish topic is not a command, and near-misses are nothing.
  CHECK(pixc::classifyTopic("/ota/progress", base) == Topic::None);
  CHECK(pixc::classifyTopic("epixc/v1/d/aabbccddeeff/ota/progress", base) == Topic::None);
  CHECK(pixc::classifyTopic("/cfgX", base) == Topic::None);
  CHECK(pixc::classifyTopic("/api", base) == Topic::None);
  CHECK(pixc::classifyTopic("", base) == Topic::None);
  CHECK(pixc::classifyTopic(nullptr, base) == Topic::None);

  // Another device's topic must never match, stripped or not.
  CHECK(pixc::classifyTopic("epixc/v1/d/001122334455/cfg", base) == Topic::None);

  // The old matcher's bug, pinned: a strstr for the FULL topic inside "/cfg" can never succeed.
  CHECK(std::strstr("/cfg", "epixc/v1/d/aabbccddeeff/cfg") == nullptr);

  // No base configured: only the stripped form can match.
  CHECK(pixc::classifyTopic("/reset", "") == Topic::Reset);
  CHECK(pixc::classifyTopic("/reset", nullptr) == Topic::Reset);
}

// ---------------------------------------------------------------------------------------------
// B2: debug output must never carry the PIN or a password, even on a dev build.
// ---------------------------------------------------------------------------------------------
static void redacts(const char* in, const char* want) {
  char buf[512];
  std::snprintf(buf, sizeof(buf), "%s", in);
  pixc::redactJsonSecrets(buf);
  const bool ok = std::strcmp(buf, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  in:   %s\n  got:  %s\n  want: %s\n", in, buf, want);
}

static void testRedaction() {
  // The cloud /cfg payload that carries the rotated PIN (DeviceService.buildCfg).
  redacts(R"({"def":{"bri":191},"um":{"PixcConnect":{"settingsPin":"4821"}}})",
          R"({"def":{"bri":191},"um":{"PixcConnect":{"settingsPin":"****"}}})");
  // The LAN body the app sends with every request.
  redacts(R"({"on":true,"pin":"1234"})", R"({"on":true,"pin":"****"})");
  // MQTT credential push and Wi-Fi provisioning.
  redacts(R"({"if":{"mqtt":{"en":true,"user":"aabbccddeeff","psk":"0123abcd"}}})",
          R"({"if":{"mqtt":{"en":true,"user":"aabbccddeeff","psk":"********"}}})");
  redacts(R"({"nw":{"ins":[{"ssid":"Home","psk":"hunter2"}]}})",
          R"({"nw":{"ins":[{"ssid":"Home","psk":"*******"}]}})");
  // Bare values, whitespace, mixed case, escapes.
  redacts(R"({"PIN" : 1234, "bri":5})", R"({"PIN" : ****, "bri":5})");
  redacts(R"({"password":"a\"b"})", R"({"password":"****"})");
  redacts(R"({"ota":{"pwd":"wledota"}})", R"({"ota":{"pwd":"*******"}})");
  // Values that merely LOOK like secret keys are left alone; so is non-secret data.
  redacts(R"({"ssid":"pin","v":true})", R"({"ssid":"pin","v":true})");
  redacts(R"({"seg":[{"col":[[255,0,0]]}]})", R"({"seg":[{"col":[[255,0,0]]}]})");
  // Truncated input must not read past the terminator.
  redacts(R"({"pin":"12)", R"({"pin":"**)");
  redacts(R"({"pi)", R"({"pi)");
  CHECK(pixc::isSecretKey("mqttPass", 8));
  CHECK(pixc::isSecretKey("lan_secret", 10));
  CHECK(!pixc::isSecretKey("ping", 4));
  CHECK(!pixc::isSecretKey("user", 4));
}

// ---------------------------------------------------------------------------------------------
// S3: per-address backoff and a global ceiling that never locks out a correct PIN elsewhere.
// ---------------------------------------------------------------------------------------------
// An address on 192.168.1.0/24 as lwIP stores it on a little-endian CPU (first octet low byte).
static uint32_t lanIp(uint8_t host) { return 192u | (168u << 8) | (1u << 16) | (uint32_t(host) << 24); }

static void testPinGuardBackoff() {
  pixc::PinGuard g;
  const uint32_t a = lanIp(66);
  uint64_t t = 1000000;
  CHECK(g.mayTry(a, t));
  g.onWrong(a, t);
  uint64_t wait = 0;
  CHECK(!g.mayTry(a, t + 999, &wait));
  CHECK(wait == 1);
  CHECK(g.mayTry(a, t + 1000));
  g.onWrong(a, t + 1000);                       // 2nd: 2 s
  CHECK(!g.mayTry(a, t + 2999));
  CHECK(g.mayTry(a, t + 3000));
  g.onWrong(a, t + 3000);                       // 3rd: 4 s
  CHECK(!g.mayTry(a, t + 6999));
  CHECK(g.mayTry(a, t + 7000));
  g.onRight(a);                                 // a right PIN forgives the address
  g.onWrong(a, t + 7000);
  CHECK(g.mayTry(a, t + 8000));                 // back to 1 s
}

static void testPinGuardOwnerNeverLockedOut() {
  pixc::PinGuard g;
  const uint32_t attacker = lanIp(66), owner = lanIp(20), sync = lanIp(21);
  uint64_t t = 5000;
  int ownerRefused = 0;
  // A day of an attacker guessing as fast as it is allowed, every 100 ms, while the owner's app
  // and Sync talk to the light every second with the right PIN.
  for (uint64_t ms = 0; ms < 24ULL * 3600 * 1000; ms += 100) {
    if (g.mayTry(attacker, t + ms)) g.onWrong(attacker, t + ms);
    if (ms % 1000 == 0) {
      if (g.mayTry(owner, t + ms)) g.onRight(owner); else ownerRefused++;
      if (g.mayTry(sync, t + ms)) g.onRight(sync); else ownerRefused++;
    }
  }
  CHECK(ownerRefused == 0);
}

static void testPinGuardCeiling() {
  // A single address: the backoff alone keeps it to a few dozen guesses a day.
  {
    pixc::PinGuard g;
    int guesses = 0;
    for (uint64_t ms = 0; ms < 24ULL * 3600 * 1000; ms += 100) {
      if (g.mayTry(lanIp(66), ms + 1)) { g.onWrong(lanIp(66), ms + 1); guesses++; }
    }
    std::printf("  single-host attacker: %d wrong guesses/day\n", guesses);
    CHECK(guesses <= 40);
  }
  // Every address of the /24, rotating as fast as allowed: bounded by budget + one per address.
  {
    pixc::PinGuard g;
    int guesses = 0;
    for (uint64_t sec = 0; sec < 24ULL * 3600; sec++) {
      for (int h = 1; h < 255; h++) {
        const uint64_t now = sec * 1000 + 1;
        if (g.mayTry(lanIp(uint8_t(h)), now)) { g.onWrong(lanIp(uint8_t(h)), now); guesses++; }
      }
    }
    std::printf("  whole-/24 attacker:   %d wrong guesses/day\n", guesses);
    CHECK(guesses <= pixc::PinGuard::kBudgetBurst + 96 + 256);
    CHECK(guesses >= 100);                      // and the bound is not vacuous
  }
  // With the budget spent, a fresh host is still heard exactly once.
  {
    pixc::PinGuard g;
    for (int i = 0; i < 40; i++) {
      const uint32_t ip = lanIp(uint8_t(100 + i));
      if (g.mayTry(ip, 10)) g.onWrong(ip, 10);
    }
    CHECK(g.tokens() == 0);
    CHECK(g.mayTry(lanIp(200), 10));            // never failed: evaluated
    g.onWrong(lanIp(200), 10);
    CHECK(!g.mayTry(lanIp(200), 2000));         // failed with no budget: refused until a token
    CHECK(g.mayTry(lanIp(201), 2000));          // a different fresh host: still heard
  }
}

// ---------------------------------------------------------------------------------------------
// R1/R3: retry timing.
// ---------------------------------------------------------------------------------------------
static void testBackoff() {
  // Attempt 0 waits between base/2 and base; each attempt doubles; the cap holds; jitter spans.
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 0) == 1000);
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 1000) == 2000);
  CHECK(pixc::backoffWithJitter(0, 2000, 300000, 1001) == 1000);
  CHECK(pixc::backoffWithJitter(3, 2000, 300000, 0) == 8000);
  CHECK(pixc::backoffWithJitter(3, 2000, 300000, 8000) == 16000);
  CHECK(pixc::backoffWithJitter(20, 2000, 300000, 0) == 150000);
  CHECK(pixc::backoffWithJitter(255, 2000, 300000, 0xFFFFFFFFu) <= 300000);
  CHECK(pixc::backoffPlusMinus20(0, 5000, 300000, 0) == 4000);
  CHECK(pixc::backoffPlusMinus20(0, 5000, 300000, 2000) == 6000);
  CHECK(pixc::backoffPlusMinus20(10, 5000, 300000, 0) == 240000);
  for (uint32_t r = 0; r < 50000; r += 13) {
    const uint32_t v = pixc::backoffPlusMinus20(2, 5000, 300000, r);
    CHECK(v >= 16000 && v <= 24000);
  }
  for (uint32_t r = 0; r < 100000; r += 7) {
    const uint32_t v = pixc::backoffWithJitter(5, 2000, 300000, r);
    CHECK(v >= 32000 && v <= 64000);
  }
}

// ---------------------------------------------------------------------------------------------
// C2: the SSID in the health JSON is escaped.
// ---------------------------------------------------------------------------------------------
static void escapes(const char* in, const char* want, size_t cap = 128) {
  char out[128];
  pixc::jsonEscape(in, out, cap);
  const bool ok = std::strcmp(out, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  in: %s\n  got: %s\n  want: %s\n", in, out, want);
}

static void testJsonEscape() {
  escapes("Home", "Home");
  escapes("Bob's \"5G\"", "Bob's \\\"5G\\\"");
  escapes("a\\b", "a\\\\b");
  escapes("tab\there", "tab\\there");
  escapes("\x01x", "\\u0001x");
  escapes("வீடு", "வீடு");                     // UTF-8 passes through
  escapes("\"\"\"\"", "\\\"\\\"", 6);      // never splits an escape at the cap
  escapes(nullptr, "");
}

// ---------------------------------------------------------------------------------------------
// L7/L10: the health report is never cut, and carries the heap's fragmentation.
// ---------------------------------------------------------------------------------------------
static void testHealthPayload() {
  // The widest report there can be: an SSID of 32 control bytes, the widest numbers, an over-long
  // version. It has to fill the buffer to the byte and still parse.
  char ssid[33];
  for (int i = 0; i < 32; i++) ssid[i] = '\x01';
  ssid[32] = 0;
  std::string fw(80, 'v');
  pixc::Health h{INT_MIN, INT_MIN, ssid, "255.255.255.255", UINT32_MAX, UINT32_MAX, UINT32_MAX,
                 UINT32_MAX, fw.c_str()};
  char buf[pixc::kHealthPayloadMax];
  const int n = pixc::formatHealthPayload(buf, sizeof(buf), h);
  std::printf("  health report: worst case %d bytes, buffer %zu\n", n, sizeof(buf));
  CHECK(n == static_cast<int>(pixc::kHealthPayloadMax) - 1);    // the bound is exact, not loose
  DynamicJsonDocument doc(2048);
  CHECK(!deserializeJson(doc, buf));
  CHECK(std::strlen(doc["ssid"].as<const char*>()) == 32);
  CHECK(doc["heap_largest"].as<uint32_t>() == UINT32_MAX);
  CHECK(doc["fw_version"].as<std::string>().size() == pixc::kFwVersionMax);
  // A '"' or '\\' in the SSID keeps it valid (audit C2), and the new heap fields are there.
  pixc::Health t{-61, 78, "Bob's \"5G\" \\ net", "192.168.1.20", 180000, 90000, 60000, 3600,
                 "17.0.1-pixc1"};
  CHECK(pixc::formatHealthPayload(buf, sizeof(buf), t) > 0);
  DynamicJsonDocument d2(1024);
  CHECK(!deserializeJson(d2, buf));
  CHECK(d2["ssid"] == "Bob's \"5G\" \\ net");
  CHECK(d2["free_heap"] == 180000);
  CHECK(d2["heap_largest"] == 90000);
  CHECK(d2["heap_min"] == 60000);
  CHECK(d2["uptime"] == 3600);
  CHECK(d2["rssi"] == -61 && d2["signal"] == 78);
}

// ---------------------------------------------------------------------------------------------
// P2: the power-cycle factory reset, and factory hotspot data.
// ---------------------------------------------------------------------------------------------
// A boot of the unit as pixc_device.cpp drives the gesture: load from "NVS", boot(), then tick()
// every 10 ms until the power goes at `onMs`. Returns true if the reset was requested.
struct GestureNvs { uint8_t n = 0; bool pend = false; int writes = 0; };
static bool runBoot(GestureNvs& nvs, uint32_t onMs, bool powerUp = true) {
  pixc::ResetGesture g;
  g.n = nvs.n;
  g.pend = nvs.pend;
  auto store = [&]() { nvs.n = g.n; nvs.pend = g.pend; nvs.writes++; };
  if (g.boot(powerUp)) store();
  if (g.reset) return true;
  for (uint32_t t = 300; t < onMs; t += 10) if (g.tick(t)) store();   // first loop a little after boot
  return false;
}

static void testResetGesture() {
  // Five on for 3 s each, then on: that sixth power-on requests the reset, at boot.
  {
    GestureNvs nvs;
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(nvs.n == 4 && nvs.pend);
    CHECK(runBoot(nvs, 3600000));
    CHECK(nvs.n == 0 && !nvs.pend);
    CHECK(!runBoot(nvs, 3600000));                 // and only once
  }
  // The same across the window, about 2 s to 5 s, mixed; the power-on after it may be anything.
  {
    GestureNvs nvs;
    const uint32_t on[] = {2000, 5000, 1600, 5900, 2500};
    for (uint32_t ms : on) CHECK(!runBoot(nvs, ms));
    CHECK(runBoot(nvs, 200));
  }
  // A flicker: boots that die before 1.5 s never count, however many there are...
  {
    GestureNvs nvs;
    for (int i = 0; i < 50; i++) CHECK(!runBoot(nvs, 1 + (i * 97) % 1490));
    CHECK(nvs.n == 0 && !nvs.pend);
    // ...and one in the middle of a gesture breaks the chain.
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 800));
    CHECK(!runBoot(nvs, 3000));
    CHECK(nvs.n == 0 && nvs.pend);                 // one qualifying boot so far, not five
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(runBoot(nvs, 3000));                     // five from the flicker is a reset
  }
  // A normal on clears the chain: four short ons, a light left on, four more, on: no reset.
  {
    GestureNvs nvs;
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 3600000));
    CHECK(nvs.n == 0 && !nvs.pend);
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 60000));
    CHECK(nvs.n == 0 && !nvs.pend);
    // A normal on from a clean state writes twice (1.5 s and 6 s) and never counts.
    const int before = nvs.writes;
    CHECK(!runBoot(nvs, 3600000));
    CHECK(nvs.writes - before == 2);
  }
  // A slow pattern: ons of 7-10 s each (someone waiting to see the light come up) are not the
  // gesture, and one slow on among fast ones restarts it.
  {
    GestureNvs nvs;
    for (int i = 0; i < 10; i++) CHECK(!runBoot(nvs, 7000 + 300 * i));
    CHECK(nvs.n == 0 && !nvs.pend);
    for (int i = 0; i < 3; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 6500));
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));   // the chain restarts after it
    CHECK(runBoot(nvs, 3000));
  }
  // Grid flicker: 20,000 random outages with on-times from 10 ms to 20 s. A reset happens exactly
  // when the last five on-times all landed in 1.5-6 s, and (printed) that is rare.
  {
    GestureNvs nvs;
    uint32_t lcg = 12345, run = 0;
    int resets = 0;
    for (int i = 0; i < 20000; i++) {
      lcg = lcg * 1664525u + 1013904223u;
      const uint32_t on = 10 + (lcg >> 8) % 20000;
      const bool q = on >= pixc::kGestureMinOnMs && on < pixc::kGestureMaxOnMs;
      const bool r = runBoot(nvs, on);
      CHECK(r == (run == 5));                      // a reset exactly when the last five qualified
      if (r) { resets++; run = 0; continue; }      // (the wipe then starts afresh)
      run = q ? run + 1 : 0;
    }
    std::printf("  random on-times 10 ms-20 s: %d resets in 20000 power-ups\n", resets);
  }
  // Exactly at the edges: 1.5 s is in, 6 s is out.
  {
    GestureNvs nvs;
    for (int i = 0; i < 4; i++) CHECK(!runBoot(nvs, 1510));
    CHECK(nvs.n == 3 && nvs.pend);
    GestureNvs nvs2;
    for (int i = 0; i < 6; i++) CHECK(!runBoot(nvs2, 1490));
    CHECK(nvs2.n == 0 && !nvs2.pend);
    GestureNvs nvs3;
    for (int i = 0; i < 6; i++) CHECK(!runBoot(nvs3, 6010));
    CHECK(nvs3.n == 0 && !nvs3.pend);
  }
  // A crash, watchdog or brownout clears the chain: a crash loop never wipes a unit.
  {
    GestureNvs nvs;
    for (int i = 0; i < 5; i++) CHECK(!runBoot(nvs, 3000));
    CHECK(!runBoot(nvs, 3000, false));
    CHECK(nvs.n == 0);
    for (int i = 0; i < 200; i++) CHECK(!runBoot(nvs, 2500, false));
  }
  // A first loop that comes late (setup ran past 6 s) is a long boot, not a qualifying one.
  {
    pixc::ResetGesture g;
    g.n = 3; g.pend = true;
    g.boot(true);
    CHECK(g.n == 4 && !g.reset);
    CHECK(g.tick(7000));
    CHECK(g.n == 0 && !g.pend);
  }
  // A corrupt stored count clears instead of counting.
  {
    pixc::ResetGesture g;
    g.n = 200; g.pend = true;
    g.boot(true);
    CHECK(g.n == 0 && !g.reset);
  }
}

// ---------------------------------------------------------------------------------------------
// Report cadence: power every 60 s (D349), health every 30 s, state every 5 s.
// ---------------------------------------------------------------------------------------------
static void testReportCadence() {
  CHECK(pixc::kPowerIntervalMs == 60000);
  CHECK(pixc::kHealthIntervalMs == 30000);
  CHECK(pixc::kStateIntervalMs == 5000);

  // An hour of loop() at 10 ms a pass, the way the usermod drives it: one report of each at
  // connect (the announce), then whenever reportDue says so.
  const uint32_t start = 1234;
  uint32_t lastPower = start, lastHealth = start, lastState = start;
  int power = 1, health = 0, state = 1;
  for (uint32_t t = start; t < start + 3600000u; t += 10) {
    if (pixc::reportDue(t, lastState, pixc::kStateIntervalMs)) { lastState = t; state++; }
    if (pixc::reportDue(t, lastHealth, pixc::kHealthIntervalMs)) { lastHealth = t; health++; }
    if (pixc::reportDue(t, lastPower, pixc::kPowerIntervalMs)) { lastPower = t; power++; }
  }
  CHECK(power == 60);   // the announce plus 59 more inside the hour: 60 rows, not 120
  CHECK(health == 119);
  CHECK(state == 720);

  // Across the millis() wrap: due exactly one interval after the last, never early, never stuck.
  const uint32_t last = 0xFFFFFFFFu - 20000u;
  CHECK(!pixc::reportDue(last + 59999u, last, pixc::kPowerIntervalMs));
  CHECK(pixc::reportDue(last + 60000u, last, pixc::kPowerIntervalMs));
  CHECK(!pixc::reportDue(last, last, pixc::kPowerIntervalMs));

  // The power report says its own spacing, so the server integrates a mixed 30/60 s fleet.
  char buf[96];
  const int n = pixc::formatPowerPayload(buf, sizeof(buf), 1.25f, 60);
  CHECK(n > 0 && n < static_cast<int>(sizeof(buf)));
  CHECK(std::strcmp(buf, "{\"amps\":1.250,\"estimated\":true,\"interval_s\":60}") == 0);
  // The largest current and interval the usermod can report still fit its buffer.
  CHECK(pixc::formatPowerPayload(buf, sizeof(buf), 65535.0f, pixc::kPowerMaxSampleS) < static_cast<int>(sizeof(buf)));
}

// ---------------------------------------------------------------------------------------------
// M1: a flapping MQTT session must not over-count energy.
// ---------------------------------------------------------------------------------------------
// What the backend does with a sample (services/mqtt sample_seconds): round, clamp to 5-600.
static uint32_t serverSeconds(uint32_t s) { return s < 5 ? 5 : (s > 600 ? 600 : s); }

// The usermod's loop() at 10 ms a pass for `hours`, the broker session up and down on a schedule
// from `lcg`: a sample on every (re)connect (the announce), then whenever reportDue says so. The
// light draws `amps` the whole time. Returns the energy the server would record, in amp-seconds;
// `trueAs` is the energy actually drawn up to the last sample.
static double simulatePower(uint32_t seed, uint32_t upMinMs, uint32_t upMaxMs, uint32_t downMaxMs,
                            double amps, double hours, double& trueAs, int& samples) {
  uint32_t lcg = seed;
  auto rnd = [&lcg](uint32_t lo, uint32_t hi) { lcg = lcg * 1664525u + 1013904223u; return lo + (lcg >> 8) % (hi - lo + 1); };
  uint32_t last = 0;                      // _lastPower: boot
  bool up = false, announced = false;
  uint32_t flipAt = rnd(2000, 8000);      // first connect a few seconds after boot
  double reportedAs = 0;
  samples = 0;
  const uint32_t end = static_cast<uint32_t>(hours * 3600000.0);
  for (uint32_t t = 0; t < end; t += 10) {
    if (t >= flipAt) {
      up = !up;
      if (up) announced = false;          // onMqttConnect
      flipAt = t + (up ? rnd(upMinMs, upMaxMs) : rnd(10, downMaxMs));
    }
    if (!up) continue;
    const bool due = !announced || pixc::reportDue(t, last, pixc::kPowerIntervalMs);
    announced = true;
    if (!due) continue;
    const uint32_t s = pixc::powerSampleSeconds(t, last);
    if (s == 0) continue;
    reportedAs += amps * serverSeconds(s);
    samples++;
  }
  trueAs = amps * (last / 1000.0);
  return reportedAs;
}

static void testPowerReconnect() {
  // Sessions of 20-30 s with outages up to 5 s: the audit's weak-Wi-Fi light.
  {
    double truth = 0; int samples = 0;
    const double got = simulatePower(7, 20000, 30000, 5000, 1.5, 3.0, truth, samples);
    std::printf("  flapping 20-30 s: %d samples, reported/true energy %.4f\n", samples, got / truth);
    CHECK(samples > 3 * 60 * 2);                 // it really did reconnect several times a minute
    CHECK(std::fabs(got - truth) < 1e-6 * truth);
    // What the fixed 60 s used to say for the same run: at least twice the truth.
    CHECK(samples * 60.0 * 1.5 > 2.0 * truth);
  }
  // Sessions shorter than the server's 5 s floor: a span too short to report rolls forward
  // instead of being raised to 5 s.
  {
    double truth = 0; int samples = 0;
    const double got = simulatePower(11, 300, 4000, 3000, 0.8, 2.0, truth, samples);
    CHECK(samples > 0);
    CHECK(std::fabs(got - truth) < 1e-6 * truth);
  }
  // A steady session: one sample a minute, each exactly 60 s, plus the first since boot.
  {
    double truth = 0; int samples = 0;
    const double got = simulatePower(3, 2000000000u, 2000000000u, 10, 2.0, 1.0, truth, samples);
    CHECK(samples >= 59 && samples <= 61);
    CHECK(std::fabs(got - truth) < 1e-6 * truth);
  }
  // The steps themselves.
  uint32_t last = 0;
  CHECK(pixc::powerSampleSeconds(4999, last) == 0 && last == 0);      // under the floor: not sent
  CHECK(pixc::powerSampleSeconds(7400, last) == 7 && last == 7000);   // the 0.4 s carries over
  CHECK(pixc::powerSampleSeconds(67399, last) == 60 && last == 67000);
  CHECK(pixc::powerSampleSeconds(67000 + 20u * 60000u, last) == 600); // a 20-minute outage: capped
  CHECK(last == 67000 + 20u * 60000u);                                // and the rest dropped
  last = 0xFFFFFFFFu - 30000u;                                         // across the millis() wrap
  CHECK(pixc::powerSampleSeconds(last + 61000u, last) == 61);
}

static void testFactoryData() {
  CHECK(pixc::validApPsk("k7m2q9x4ab"));
  CHECK(!pixc::validApPsk("short"));
  CHECK(!pixc::validApPsk(""));
  CHECK(!pixc::validApPsk(nullptr));
  CHECK(!pixc::validApPsk("tab\there!!"));
  char name[16];
  pixc::hotspotName("aabbccddeeff", name, sizeof(name));
  CHECK(std::strcmp(name, "ePixC-EEFF") == 0);
  pixc::hotspotName("001122334a5b", name, sizeof(name));
  CHECK(std::strcmp(name, "ePixC-4A5B") == 0);
}

// ---------------------------------------------------------------------------------------------
// S6: the signed image's build descriptor is found in a stream and older images are refused.
// ---------------------------------------------------------------------------------------------
static void testDescScanner() {
  static const uint8_t magic[pixc::kBuildMagicLen] = PIXC_BUILD_MAGIC;
  // An "image": noise, a false start of the magic, the descriptor, more noise.
  std::vector<uint8_t> img;
  for (int i = 0; i < 5000; i++) img.push_back(uint8_t(i * 7 + 3));
  img.insert(img.end(), magic, magic + 5);                 // a partial match that must not stick
  img.push_back('x');
  img.insert(img.end(), magic, magic + pixc::kBuildMagicLen);
  const uint32_t build = 123456, sec = 3;
  for (int i = 0; i < 4; i++) img.push_back(uint8_t(build >> (8 * i)));
  for (int i = 0; i < 4; i++) img.push_back(uint8_t(sec >> (8 * i)));
  for (int i = 0; i < 3000; i++) img.push_back(uint8_t(i));
  // Every chunk size, so the descriptor straddles every possible boundary.
  for (size_t chunk = 1; chunk <= 40; chunk++) {
    pixc::DescScanner sc(magic);
    for (size_t o = 0; o < img.size(); o += chunk) sc.feed(img.data() + o, std::min(chunk, img.size() - o));
    CHECK(sc.found());
    CHECK(sc.build() == build);
    CHECK(sc.security() == sec);
  }
  pixc::DescScanner none(magic);
  none.feed(img.data(), 5000);
  CHECK(!none.found());

  CHECK(pixc::otaRefusal(false, 10, 1, 5, 1) != nullptr);
  CHECK(std::strcmp(pixc::otaRefusal(true, 4, 1, 5, 1), "downgrade") == 0);
  CHECK(std::strcmp(pixc::otaRefusal(true, 9, 1, 5, 2), "security downgrade") == 0);
  CHECK(pixc::otaRefusal(true, 5, 1, 5, 1) == nullptr);    // a reinstall of the same build
  CHECK(pixc::otaRefusal(true, 6, 2, 5, 1) == nullptr);
}

// ---------------------------------------------------------------------------------------------
// L5: every OTA failure word lands on the backend code that tells the customer the truth.
// ---------------------------------------------------------------------------------------------
static void otaCode(const char* raw, const char* want) {
  const char* got = pixc::otaErrorCode(raw);
  const bool ok = got != nullptr && std::strcmp(got, want) == 0;
  CHECK(ok);
  if (!ok) std::fprintf(stderr, "  \"%s\" -> %s, want %s\n", raw, got ? got : "null", want);
}

static void testOtaFailureCodes() {
  namespace f = pixc::ota_fail;
  // The one the audit found: fetching the .sig failed, which says nothing about the image.
  otaCode(f::kSigDownload, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kNoSigUrl, "OTA_FAILED");
  otaCode(f::kSigMismatch, "OTA_SIGNATURE_INVALID");
  otaCode(f::kLowMemory, "OTA_BUSY");
  otaCode(f::kNoSpace, "OTA_NO_SPACE");
  otaCode(f::kRead, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kStalled, "OTA_DOWNLOAD_FAILED");
  otaCode(f::kFlashWrite, "OTA_FLASH_FAILED");
  otaCode(f::kNoDigest, "OTA_FAILED");
  otaCode(f::kShaMismatch, "OTA_CORRUPT_DOWNLOAD");
  otaCode(f::kNoSigningKey, "OTA_FAILED");        // no dedicated backend code yet
  otaCode(f::kBadSigningKey, "OTA_FAILED");
  otaCode("http 404", "OTA_DOWNLOAD_FAILED");
  otaCode("tls/connect", "OTA_DOWNLOAD_FAILED");
  otaCode("finalize 9", "OTA_FAILED");
  otaCode(pixc::otaRefusal(false, 0, 0, 0, 0), "OTA_FAILED");              // no build descriptor
  otaCode(pixc::otaRefusal(true, 9, 1, 5, 2), "OTA_DOWNGRADE_REFUSED");      // security downgrade
  otaCode(pixc::otaRefusal(true, 4, 1, 5, 1), "OTA_DOWNGRADE_REFUSED");
  // Every word fits the 48-byte error field of the progress report.
  for (const char* w : {f::kLowMemory, f::kNoSpace, f::kRead, f::kStalled, f::kFlashWrite, f::kNoDigest,
                        f::kShaMismatch, f::kSigDownload, f::kNoSigUrl, f::kSigMismatch, f::kNoSigningKey,
                        f::kBadSigningKey})
    CHECK(std::strlen(w) < 48);
  // The copy of the backend's table, pinned on its own test inputs (OtaErrorCode.of): whole words,
  // so "already" is not "read" and a weak "signal" is not a "sig".
  otaCode("already up to date", "OTA_FAILED");
  otaCode("weak signal", "OTA_FAILED");
  otaCode("HTTP 500", "OTA_DOWNLOAD_FAILED");
  otaCode("bad sig", "OTA_SIGNATURE_INVALID");
  otaCode("image too large", "OTA_NO_SPACE");
  CHECK(pixc::otaErrorCode("") == nullptr);
  CHECK(pixc::otaErrorCode("  ") == nullptr);
  CHECK(pixc::otaErrorCode(nullptr) == nullptr);
}

static void testPinGuardV2Mode() {
  // Pairing v2: no global ceiling, two free failures, then backoff for that address only.
  pixc::PinGuard g(false, 2);
  const uint32_t a = lanIp(30), b = lanIp(31);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);
  CHECK(g.mayTry(a, 100)); g.onWrong(a, 100);          // third in a row: 1 s backoff
  CHECK(!g.mayTry(a, 500));
  CHECK(g.mayTry(a, 1100));
  for (int i = 0; i < 500; i++) {                      // a flood from many addresses...
    const uint32_t ip = lanIp(uint8_t(40 + (i % 200)));
    if (g.mayTry(ip, 2000)) g.onWrong(ip, 2000);
  }
  CHECK(g.mayTry(b, 2000));                            // ...never touches anyone else
}

int main() {
  testPinGuardV2Mode();
  testLanAuthVectors();
  testClassifyTopic();
  testDescScanner();
  testOtaFailureCodes();
  testResetGesture();
  testFactoryData();
  testReportCadence();
  testPowerReconnect();
  testJsonEscape();
  testHealthPayload();
  testBackoff();
  testRedaction();
  testPinGuardBackoff();
  testPinGuardOwnerNeverLockedOut();
  testPinGuardCeiling();
  if (g_failures == 0) {
    std::printf("pixc host tests: %d checks passed\n", g_checks);
    return EXIT_SUCCESS;
  }
  std::fprintf(stderr, "pixc host tests: %d of %d checks FAILED\n", g_failures, g_checks);
  return EXIT_FAILURE;
}
